      jest.spyOn(client.dogma, 'getEffects').mockResolvedValue(mockEffects);
    });

    when('getEffects is called', async () => {
      result = await client.dogma.getEffects();
    });

    then('the client shall return an array of effect IDs', () => {
      expect(Array.isArray(result)).toBe(true);
      expect(result.length).toBeGreaterThan(0);
      result.forEach((id: number) => {
        expect(typeof id).toBe('number');
      });
    });
  });

  test('WHEN getEffectById is called, the client shall return complete effect information', ({ given, when, then }) => {
    let result: any;
    const effectId = 11;

    given('a valid effect ID is provided', () => {
      const mockEffect = {
        effect_id: effectId,
        name: 'lowPower',
        description: 'Requires a low power slot.',
        published: true,
        display_name: 'Low Power',
        effect_category: 0,
        is_assistance: false,
        is_offensive: false,
        is_warp_safe: true,
      };

      jest.spyOn(client.dogma, 'getEffectById').mockResolvedValue(mockEffect);
    });

    when('getEffectById is called', async () => {
      result = await client.dogma.getEffectById(effectId);
    });

    then('the client shall return complete effect information', () => {
      expect(result).toBeDefined();
      expect(result.effect_id).toBe(effectId);
      expect(result.name).toBe('lowPower');
      expect(result).toHaveProperty('published');
      expect(result).toHaveProperty('is_warp_safe');
    });
  });

  test('IF the effect ID does not exist, THEN the client shall throw a not-found error', ({ given, when, then }) => {
    const invalidId = 999999999;
    let caughtError: any;

    given('an effect ID that does not exist', () => {
